package io.movetodata.catalog.library.models;

import lombok.*;
import org.hibernate.annotations.CreationTimestamp;

import javax.persistence.*;
import java.time.Instant;
import java.util.UUID;

/**
 * Immutable record of a quality-level certification event for a Data Product.
 */
@Entity
@NoArgsConstructor
@AllArgsConstructor
@Getter
@Setter
@Builder
@Table(name = "catalog_certification_history")
public class CertificationHistory {

    /** UUID primary key — generated by PostgreSQL gen_random_uuid(). */
    @Id
    @Column(name = "id", columnDefinition = "uuid", updatable = false, nullable = false)
    private String id;

    @Column(name = "data_product_id", columnDefinition = "uuid", nullable = false)
    private String dataProductId;

    /** BRONZE | SILVER | GOLD */
    @Column(name = "quality_level", nullable = false, length = 10)
    private String qualityLevel;

    @Column(name = "comment")
    private String comment;

    @Column(name = "certified_by", nullable = false, columnDefinition = "uuid")
    private UUID certifiedBy;

    @CreationTimestamp
    @Column(name = "certified_at", updatable = false)
    private Instant certifiedAt;
}
